pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 preAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        uint256 pre = uint256(preAmount);
        // Set up a pre-existing balance for the caller
        vm.prank(caller);
        c.addToBalance{value: pre}();
        uint256 balanceBefore = c.getBalance(caller);
        uint256 expectedAfter = balanceBefore + amount;
        // Ensure the sum would overflow if the check is bypassed, triggering the difference
        // The buggy check only fails when amount is >0 and balanceBefore + amount overflows
        // and (balanceBefore + amount) >= amount is true, which holds for any amount>0 and large enough balanceBefore.
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.addToBalance{value: amount}() { ok = true; } catch { ok = false; }
        if (ok) {
            // If the call didn't revert, the balance must be exactly balanceBefore + amount
            assertEq(c.getBalance(caller), expectedAfter, "balance must match deposit");
        }
        // If the call reverts, the balance must remain unchanged
        if (!ok) {
            assertEq(c.getBalance(caller), balanceBefore, "balance must not change on revert");
        }
    }
}

