pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint160 seed, uint256 amount) public {
        // seed determines the caller address
        address caller = address(uint160(seed));
        // amount is the msg.value sent to addToBalance
        // restrict amount so that the reference cannot overflow:
        // initial balance = 0, so require(amount >= 0) always true, but we must
        // ensure the reference's require(0 + amount >= 0) holds for all amounts.
        // That require works for any amount because 0+amount >= 0 always true
        // except if amount overflows uint256?  amount itself doesn't overflow.
        // The reference's require(userBalance[msg.sender] + msg.value >= userBalance[msg.sender])
        // fails when userBalance is max and amount large. We avoid that by bounding amount
        // or assume initial balance is zero. Fuzzer can set amount to any value less than
        // type(uint256).max to keep reference safe. We'll bound amount <= type(uint256).max - 1
        // so that initial balance (0) + amount never overflows uint256. Actually any amount is fine
        // for reference because 0 + amount = amount >= 0 always true. So no need to bound.
        // However, if amount is huge and caller's balance becomes near max, further calls could
        // revert. We only make one call here, so no issue.
        // The important thing: the buggy version wraps on overflow. If amount is large enough
        // that (prevBalance + amount) wraps to a small value, the balance decreases.
        // To trigger that with fuzzer, we need prevBalance > 0. So we first deposit something
        // to get a non-zero balance, then apply the fuzzed amount in a second call.
        // We'll deposit a base amount first, then add fuzzed amount.
        vm.assume(amount > 0); // avoid zero value calls; nonzero needed for interesting behavior
        uint256 baseDeposit = 1000;
        vm.deal(caller, baseDeposit + amount);
        vm.prank(caller);
        c.addToBalance{value: baseDeposit}();
        uint256 balanceBefore = c.getBalance(caller);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 balanceAfter = c.getBalance(caller);
        // The property: balanceAfter should be >= balanceBefore.
        // For the reference: balanceAfter = balanceBefore + amount (since require passes).
        // So balanceAfter >= balanceBefore always.
        // For the mutant: if balanceBefore + amount overflows, balanceAfter wraps to a small number < balanceBefore.
        assertTrue(balanceAfter >= balanceBefore);
    }
}

